import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble, capped at six active factors and normalized to 1.
FACTOR_WEIGHTS = {"clv": .25, "peer": .21, "reversal": .18, "momentum": .16, "shock": .14, "hv_reversal": .06}
MIN_W, MAX_W, REBALANCE_DAYS = .015, .16, 10
last_decision = None

def rank_map(vals):
    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    n = len(good)
    if n > 1:
        for i, (s, _) in enumerate(good): out[s] = (i + 1.) / n
    return out

def simplex_box(raw):
    # Iterative capped simplex; preserves all 15 assets and exactly unit gross weight.
    w = {s: max(float(raw.get(s, 0.0)), 1e-9) for s in UNIVERSE}
    for _ in range(100):
        free = [s for s in UNIVERSE if MIN_W < w[s] < MAX_W]
        for s in UNIVERSE: w[s] = min(MAX_W, max(MIN_W, w[s]))
        fixed_sum = sum(w[s] for s in UNIVERSE if s not in free)
        if not free: break
        rem = 1.0 - fixed_sum
        z = sum(max(w[s], 1e-9) for s in free)
        for s in free: w[s] = rem * w[s] / z
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global last_decision
    account = get_account_dict()
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=90)
        if df is None or len(df) < 30: continue
        df = df.sort_values("date").reset_index(drop=True)
        c, h, l = [np.asarray(df[x], dtype=float) for x in ("close", "high", "low")]
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.
        data[s] = (c, h, l, r, str(df.iloc[-1]["date"]))
    if len(data) < 12: return
    decision = max(x[4] for x in data.values())
    if last_decision is not None:
        try:
            if (np.datetime64(decision, "D") - np.datetime64(last_decision, "D")) / np.timedelta64(1, "D") < REBALANCE_DAYS: return
        except Exception: return

